import random
from itertools import combinations

def check_graph(edges):
    n = 9
    deg = [0]*n
    for u,v in edges:
        deg[u] += 1
        deg[v] += 1
    if any(d < 2 or d > 3 for d in deg):
        return False
    e = len(edges)
    if not (12 <= e <= 17):
        return False
    # chromatic number <=4 and >=2. Since max deg <=3, chi<=4 always. chi>=2 since min deg>=2 => not empty.
    # But let's compute chi quickly using brute force for safety.
    # Build adjacency
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)
    # quick chi compute via backtracking
    colors = [-1]*n
    def dfs(v, maxc):
        if v == n:
            return True
        used = [False]*(maxc+1)
        for nb in adj[v]:
            if colors[nb] != -1:
                used[colors[nb]] = True
        for c in range(maxc+1):
            if not used[c]:
                colors[v] = c
                if dfs(v+1, maxc):
                    return True
                colors[v] = -1
        return False
    chi = 1
    while chi <= 4:
        colors = [-1]*n
        if dfs(0, chi-1):
            break
        chi += 1
    if chi > 4 or chi < 2:
        return False
    return True

